tries:=make([]uint64,len(queries));started:=time.Now()
defer func(){
 path:=os.Getenv("GTRON_ROUTING_QUERY_TRACE");if path==""{return}
 elapsed:=time.Since(started).Nanoseconds()
 rows:=make([]map[string]any,len(queries))
 for i,q:=range queries{
  row:=map[string]any{"flat":q.FlatDomain,"owner":q.Owner.Hex(),"generation":q.Generation,"domain":q.Domain,"key_hex":hex.EncodeToString(q.Key),"segments_visited":tries[i],"found":out[i]!=nil}
  if out[i]!=nil{row["tx"]=out[i].TxNum;row["seq"]=out[i].Seq;row["prev_exists"]=out[i].PrevExists;row["prev_bytes"]=len(out[i].Prev)}
  rows[i]=row
 }
 event:=map[string]any{"from":fromTxNum,"to":toTxNum,"elapsed_ns":elapsed,"queries":rows};if retErr!=nil{event["error"]=retErr.Error()}
 data,e:=json.Marshal(event);if e!=nil{return};f,e:=os.OpenFile(path,os.O_CREATE|os.O_APPEND|os.O_WRONLY,0600);if e==nil{f.Write(append(data,'\n'));f.Close()}
}()
